<!doctype html><html><head><meta charset="utf-8"><title>{{ $title }}</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#111}h1{margin-bottom:4px}.muted{color:#666}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.card{border:1px solid #ddd;padding:14px}.value{font-size:20px;font-weight:700;margin-top:6px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}th{background:#f5f5f5}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="window.print()">Print / Save as PDF</button></div><h1>{{ $title }}</h1><div class="muted">Generated {{ now()->format('d M Y H:i') }}</div><div class="grid"><div class="card">Gross sales<div class="value">₦{{ number_format($stats['gross_sales'],2) }}</div></div><div class="card">Net revenue<div class="value">₦{{ number_format($stats['net_revenue'],2) }}</div></div><div class="card">Commissions<div class="value">₦{{ number_format($stats['commission_total'],2) }}</div></div><div class="card">Orders<div class="value">{{ number_format($stats['orders']) }}</div></div></div><table><thead><tr><th>Date</th><th>Orders</th><th>Sales</th><th>Commissions</th><th>Operational net</th></tr></thead><tbody>@foreach($series as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['orders'] }}</td><td>₦{{ number_format($row['sales'],2) }}</td><td>₦{{ number_format($row['commissions'],2) }}</td><td>₦{{ number_format(max(0,$row['sales']-$row['commissions']),2) }}</td></tr>@endforeach</tbody></table></body></html>
